VALUES = ((1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"))


def _to_int(text):
    digits = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, ch in enumerate(text):
        value = digits[ch]
        if i + 1 < len(text) and digits[text[i + 1]] > value:
            total -= value
        else:
            total += value
    return total


def roman_add(a, b):
    n = _to_int(a) + _to_int(b)
    if n > 3999:
        raise ValueError("too large")
    out = ""
    for value, text in VALUES:
        while n >= value:
            out += text
            n -= value
    return out

from collections import Counter


def min_window(s, t):
    if not t or len(t) > len(s):
        return ""
    need = Counter(t)
    missing = len(t)
    best = (None, None)
    left = 0
    for right, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        if missing == 0:
            while need[s[left]] < 0:
                need[s[left]] += 1
                left += 1
            if best[0] is None or right - left < best[1] - best[0]:
                best = (left, right)
            need[s[left]] += 1
            missing += 1
            left += 1
    return "" if best[0] is None else s[best[0]:best[1] + 1]

def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1
            chunk = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quote")
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chunk.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                chunk.append(line[i])
                i += 1
            if i < n and line[i] != ",":
                raise ValueError("garbage after closing quote")
            fields.append("".join(chunk))
        else:
            j = line.find(",", i)
            if j < 0:
                j = n
            fields.append(line[i:j])
            i = j
        if i >= n:
            return fields
        i += 1
        if i == n:
            fields.append("")
            return fields

def evaluate(expr):
    tokens = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            tokens.append(ch)
            i += 1
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def take():
        pos[0] += 1
        return tokens[pos[0] - 1]

    def unary():
        token = peek()
        if token == "-":
            take()
            return -unary()
        if token == "+":
            take()
            return unary()
        if token == "(":
            take()
            value = expression()
            take()
            return value
        return take()

    def term():
        value = unary()
        while peek() in ("*", "/"):
            op = take()
            right = unary()
            if op == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                quotient = abs(value) // abs(right)
                value = quotient if (value < 0) == (right < 0) else -quotient
        return value

    def expression():
        value = term()
        while peek() in ("+", "-"):
            op = take()
            right = term()
            value = value + right if op == "+" else value - right
        return value

    return expression()

from collections import deque


def shortest_clear_path(grid):
    n = len(grid)
    if grid[0][0] or grid[n - 1][n - 1]:
        return -1
    seen = [[False] * n for _ in range(n)]
    seen[0][0] = True
    queue = deque([(0, 0, 1)])
    while queue:
        r, c, d = queue.popleft()
        if r == n - 1 and c == n - 1:
            return d
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and not seen[nr][nc] and not grid[nr][nc]:
                    seen[nr][nc] = True
                    queue.append((nr, nc, d + 1))
    return -1

def word_break_sentences(s, words):
    vocabulary = set(words)
    lengths = sorted(set(len(w) for w in vocabulary))
    memo = {}

    def solve(start):
        if start == len(s):
            return [""]
        if start in memo:
            return memo[start]
        found = []
        for length in lengths:
            token = s[start:start + length]
            if len(token) == length and token in vocabulary:
                for rest in solve(start + length):
                    found.append(token if rest == "" else token + " " + rest)
        memo[start] = found
        return found

    import sys
    sys.setrecursionlimit(max(10000, len(s) * 4 + 100))
    return sorted(solve(0)) if s else [""]

def run_ledger(events):
    balances = {}
    rejected = []
    for index, event in enumerate(events):
        kind = event[0]
        if kind == "transfer":
            _, source, destination, amount = event
            balances.setdefault(source, 0)
            balances.setdefault(destination, 0)
            if amount <= 0 or source == destination or balances[source] < amount:
                rejected.append(index)
            else:
                balances[source] -= amount
                balances[destination] += amount
        else:
            _, account, amount = event
            balances.setdefault(account, 0)
            if amount <= 0 or (kind == "withdraw" and balances[account] < amount):
                rejected.append(index)
            elif kind == "deposit":
                balances[account] += amount
            else:
                balances[account] -= amount
    return balances, rejected

def next_fire(expr, after):
    parts = expr.split(" ")
    if len(parts) != 2:
        raise ValueError("two fields")

    def parse(text, limit):
        if text == "*":
            return lambda value: True
        if text.startswith("*/"):
            step = text[2:]
            if not step.isdigit() or int(step) == 0:
                raise ValueError("bad step")
            step = int(step)
            return lambda value: value % step == 0
        if not text.isdigit() or int(text) >= limit:
            raise ValueError("bad value")
        number = int(text)
        return lambda value: value == number

    minute_ok = parse(parts[0], 60)
    hour_ok = parse(parts[1], 24)
    t = after + 1
    while True:
        if minute_ok(t % 60) and hour_ok((t // 60) % 24):
            return t
        t += 1

from collections import deque


def knight_min_moves(n, src, dst):
    if src == dst:
        return 0
    dist = {src: 0}
    queue = deque([src])
    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)):
            nxt = (r + dr, c + dc)
            if 0 <= nxt[0] < n and 0 <= nxt[1] < n and nxt not in dist:
                dist[nxt] = dist[(r, c)] + 1
                if nxt == dst:
                    return dist[nxt]
                queue.append(nxt)
    return -1
